   380	/* this function reads a (small) unsigned integer
   381	 * from asn1 structs. Combines the read and the convertion
   382	 * steps.
   383	 */
   384	int
   385	_gnutls_x509_read_uint(ASN1_TYPE node, const char *value,
   386	                       unsigned int *ret)
   387	{
   388	        int len, result;
   389	        uint8_t *tmpstr;
   390	
   391	        len = 0;
   392	        result = asn1_read_value(node, value, NULL, &len);
   393	        if (result != ASN1_MEM_ERROR) {
   394	                return _gnutls_asn2err(result);
   395	        }
   396	
   397	        tmpstr = gnutls_malloc(len);
   398	        if (tmpstr == NULL) {
   399	                gnutls_assert();
   400	                return GNUTLS_E_MEMORY_ERROR;
   401	        }
   402	
   403	        result = asn1_read_value(node, value, tmpstr, &len);
   404	
   405	        if (result != ASN1_SUCCESS) {
   406	                gnutls_assert();
   407	                gnutls_free(tmpstr);
   408	                return _gnutls_asn2err(result);
   409	        }
   410	
   411	        if (len == 1)
   412	                *ret = tmpstr[0];
   413	        else if (len == 2)
   414	                *ret = _gnutls_read_uint16(tmpstr);
   415	        else if (len == 3)
   416	                *ret = _gnutls_read_uint24(tmpstr);
   417	        else if (len == 4)
   418	                *ret = _gnutls_read_uint32(tmpstr);
   419	        else {
   420	                gnutls_assert();
   421	                gnutls_free(tmpstr);
   422	                return GNUTLS_E_INTERNAL_ERROR;
   423	        }
   424	
   425	        gnutls_free(tmpstr);
   426	
   427	        return 0;
   428	}
   429	
   430	/* Writes the specified integer into the specified node.
   431	 */
   432	int
   433	_gnutls_x509_write_uint32(ASN1_TYPE node, const char *value, uint32_t num)
   434	{
   435	        uint8_t tmpstr[5];
   436	        int result;
   437	
   438	        tmpstr[0] = 0;
   439	        _gnutls_write_uint32(num, tmpstr+1);
   440	
   441	        if (tmpstr[1] > SCHAR_MAX) {
   442	                result = asn1_write_value(node, value, tmpstr, 5);
   443	        } else {
   444	                result = asn1_write_value(node, value, tmpstr+1, 4);
   445	        }
   446	
   447	        if (result != ASN1_SUCCESS) {
   448	                gnutls_assert();
   449	                return _gnutls_asn2err(result);
   450	        }
   451	
   452	        return 0;
   453	}
