                        addf(str, "error importing public key: %s\n", gnutls_strerror(ret));
                print_pk_name(str, crt); /* print basic info only */
                ret = 0;
                goto cleanup;
        }

        print_pubkey(str, _("Subject "), pubkey, &params, format);
        ret = 0;

 cleanup:
        if (pubkey)
                gnutls_pubkey_deinit(pubkey);

        return ret;
}

